        ["d", "distância entre os centros das duas circunferências"],
        ["dx, dy", "diferença entre as coordenadas x e entre as coordenadas y dos dois centros"],
        ["|r1 − r2|", "módulo: o raio maior menos o menor, sempre positivo"],
